import {modeProgress} from './modes.js';
import {CHARACTERS} from './content.js';
import {Game} from './engine.js?v=16';
import {compatible,muteReplay,attachRecording,clone} from './replay-log.js';
import {sha256} from './state-hash.js';
import {MAPS} from './maps.js';
import {settlement} from './results-panel.js';
const turnIndexes=new WeakMap();
export const ARCHIVE_KEY='naiwa-local-history-v1';
export function validateReplay(raw){const r=typeof raw==='string'?JSON.parse(raw):clone(raw);if(!r||typeof r!=='object')throw Error('回放文件无效');const legacy=r.formatVersion===0;if(legacy){r.formatVersion=1;r.initialHash=Game.restore(r.initial)?.stateHash();}compatible(r);const g=Game.restore(r.initial);if(!g||g.stateHash()!==r.initialHash)throw Error('存档状态不兼容。');muteReplay(g);let previous=r.initialHash;const turns=[0];for(const [index,e] of r.commands.entries()){const round=g.s.round,pid=g.s.current,alive=g.player.alive,reason=g.s.debt?.label;if(!g.dispatch(e.command).ok||g.stateHash()!==e.stateHash)throw Error('命令或规则状态不一致，停止播放。');const cause=alive&&!g.s.players[pid].alive?reason||'未知原因':null;if(legacy)e.cause=cause;if(e.cause!==cause)throw Error('破产原因校验失败');const chain=sha256(previous+JSON.stringify(e.command)+e.stateHash+JSON.stringify(e.cause));if(legacy)e.chain=chain;if(e.chain!==chain)throw Error('命令校验失败，回放可能被修改。');if(round!==g.s.round||pid!==g.s.current)turns.push(index+1);previous=e.chain;}turnIndexes.set(r,turns);if(g.stateHash()!==r.finalHash)throw Error('最终哈希不一致。');return r;}

export class ReplayPlayer{
 constructor(raw){this.record=validateReplay(raw);this.turns=turnIndexes.get(this.record);this.playing=false;this.speed=1;this.seek(0);}
 seek(index){if(!Number.isInteger(index)||index<0||index>this.record.commands.length)throw Error('位置无效');const g=Game.restore(this.record.initial);muteReplay(g);for(let i=0;i<index;i++){const e=this.record.commands[i];if(!g.dispatch(e.command).ok||g.stateHash()!==e.stateHash)throw Error('播放状态校验失败');}this.game=g;this.index=index;return g;}
 step(){if(this.index>=this.record.commands.length){this.playing=false;return false;}const e=this.record.commands[this.index];if(!this.game.dispatch(e.command).ok||this.game.stateHash()!==e.stateHash){this.playing=false;throw Error('回放校验失败');}this.index++;return true;}
 turn(direction){const marks=this.turns,target=direction>0?marks.find(n=>n>this.index):marks.filter(n=>n<this.index).at(-1);this.playing=false;return this.seek(target??(direction>0?this.record.commands.length:0));}
 continueGame(){if(this.game.s.phase==='finished')throw Error('对局已结束，请先跳转。');const g=Game.restore(this.game.s);const r=clone(this.record);r.commands=r.commands.slice(0,this.index);r.finalHash=g.stateHash();attachRecording(g,r,true);return g;}
}
export function resultSummary(g){return ['奶家本地战绩 · 非竞技认证',MAPS[g.s.mapVersion].name+' · 第 '+g.s.round+' / '+g.s.maxRounds+' 轮',...settlement(g).map(r=>{const a=r.assets;return `第${r.rank}名 ${g.char(r.player).name}${r.player.alive?'':'（破产）'}：净资产${a.total}；现金${a.cash}、存款${a.deposit}、地产${a.property}、股票市值${a.stocks}、交通工具${a.vehicle}、贷款${a.loan}`;})].join('\n');}
export function readHistory(storage){try{const d=JSON.parse(storage.getItem(ARCHIVE_KEY)||'null');if(d&&d.version!==1)return {version:d.version,matches:[],scores:[],incompatible:true};return d?.version===1&&Array.isArray(d.matches)?{version:1,matches:d.matches.filter(m=>m?.replay?.initial&&Array.isArray(m.replay.commands)).slice(-20),scores:Array.isArray(d.scores)?d.scores:d.matches.filter(m=>m?.results).map(({id,rounds,results,causes})=>({id,rounds,results,causes}))}:{version:1,matches:[],scores:[]};}catch{return {version:1,matches:[],scores:[],incompatible:true};}}
export function storeReplay(storage,g,record){const d=readHistory(storage);if(d.incompatible)throw Error('本地战绩版本不兼容');const id=record.captureId||record.initialHash;let item=d.matches.find(m=>m.id===id);if(!item){item={id};d.matches.push(item);}item.updatedAt=Date.now();item.replay=clone(record);if(g.s.phase==='finished'){item.summary=resultSummary(g);item.rounds=g.s.round;item.results=settlement(g).map(r=>({character:r.player.character,winner:g.s.mode.goal.type==='netWorth'?modeProgress(g).find(p=>p.playerId===r.player.id).success:r.winner,bankrupt:!r.player.alive}));item.causes=record.commands.filter(e=>e.cause).map(e=>e.cause).concat(record.initial.players.filter(p=>!p.alive).map(()=>'接续前，原因未知'));const score={id,rounds:item.rounds,results:item.results,causes:item.causes};d.scores=d.scores.filter(s=>s?.id!==id);d.scores.push(score);}
 // Bound local storage; eviction is explicit in the UI documentation.
 d.matches=d.matches.filter(m=>m!==item);d.matches.push(item);d.matches=d.matches.slice(-20);for(;;){try{storage.setItem(ARCHIVE_KEY,JSON.stringify(d));break;}catch(error){if(d.matches.length<=1)throw error;d.matches.shift();}}return d;}
const complete=m=>Array.isArray(m?.results)&&Number.isInteger(m.rounds)&&m.rounds>0;
export function causeStats(d){const rows=Object.create(null);for(const m of (d.scores||d.matches).filter(complete))for(const cause of Array.isArray(m.causes)?m.causes:[])if(typeof cause==='string')rows[cause]=(rows[cause]||0)+1;return rows;}
export function localStats(d){const rows=Object.create(null);for(const m of (d.scores||d.matches).filter(complete)){for(const r of m.results){if(!CHARACTERS.some(c=>c.id===r?.character))continue;const a=rows[r.character]??={uses:0,wins:0,rounds:0,bankruptcies:0};a.uses++;a.wins+=Number(r.winner===true);a.rounds+=m.rounds;a.bankruptcies+=Number(r.bankrupt===true);}}return rows;}
